// 📝 The requirement keys, in the prototype REQUIREMENT order. NeedMask bits index this enum; the ④ input loop reads a key's
//    document field through DocumentFieldSet and states its shortfall through RequirementShortfall.
enum ConstructionRequirementKey
{
    Requirement_Workplane = 0,
    Requirement_Closed = 1,
    Requirement_Planar = 2,
    Requirement_Axis = 3,
    Requirement_Path = 4,
    Requirement_Uniform = 5,
    Requirement_Pending = 6,
    Requirement_Support = 7,
    Requirement_Tangent = 8,
    Requirement_Opening = 9,
    Requirement_Refplane = 10,
    Requirement_Imagery = 11,
    Requirement_Measurable = 12,
    ConstructionRequirementCount = 13,
};

namespace
{
    // The shortfall prose for each requirement key, REQUIREMENT[key][1] verbatim.
    const char* const RequirementShortfall[ConstructionRequirementCount] =
    {
        "set a workplane",   // workplane: WorkplaneActivation
        "profile must close",   // closed: ClosedProfileCondition
        "profile must be planar",   // planar: PlanarProfileCondition
        "needs an axis",   // axis: AxisAvailability
        "needs a path",   // path: PathAvailability
        "profiles must share closure",   // uniform: UniformClosureCondition
        "no pending geometry",   // pending: PendingGeometryCondition
        "needs material to reach",   // support: SupportMaterialCondition
        "needs a shared endpoint",   // tangent: TangentEndpointCondition
        "needs an opening",   // opening: OpeningCondition
        "needs a reference plane",   // refplane: ReferencePlaneCondition
        "needs an imported source",   // imagery: SourceImageryCondition
        "needs a measurable component",   // measurable: MeasurableCondition
    };

    // Read a requirement key's backing document condition — REQUIREMENT[key][0] resolved against the live document. The workplane
    // key is special-cased in the gate (② promoted above all else) and never reached through here in the ④ loop.
    bool DocumentFieldSet(int RequirementKey, const ConstructionDocument& Document)
    {
        switch (RequirementKey)
        {
            case Requirement_Workplane: return Document.WorkplaneActivation;
            case Requirement_Closed: return Document.ClosedProfileCondition;
            case Requirement_Planar: return Document.PlanarProfileCondition;
            case Requirement_Axis: return Document.AxisAvailability;
            case Requirement_Path: return Document.PathAvailability;
            case Requirement_Uniform: return Document.UniformClosureCondition;
            case Requirement_Pending: return Document.PendingGeometryCondition;
            case Requirement_Support: return Document.SupportMaterialCondition;
            case Requirement_Tangent: return Document.TangentEndpointCondition;
            case Requirement_Opening: return Document.OpeningCondition;
            case Requirement_Refplane: return Document.ReferencePlaneCondition;
            case Requirement_Imagery: return Document.SourceImageryCondition;
            case Requirement_Measurable: return Document.MeasurableCondition;
            default: return true;
        }
    }
}

