//----------------------------------------------------------------------------------------------------------------------
//                                                    THE RAISING LAW
//----------------------------------------------------------------------------------------------------------------------

bool RaiseDimension(ConstructionDimension Dimension, bool ClosedCondition, ConstructionDimension& Raised)
{
    switch (Dimension)
    {
        case ConstructionDimension::Vertex: Raised = ConstructionDimension::Edge; return true;  // a point swept traces a curve
        case ConstructionDimension::Edge:   Raised = ConstructionDimension::Face; return true;  // a curve swept sweeps out a surface
        // 🔴 The theorem. An open chain cannot bound a face, so it can never reach Solid; a closed one rides the chain up to Solid.
        case ConstructionDimension::Wire:
            Raised = ClosedCondition ? ConstructionDimension::Solid : ConstructionDimension::Shell; return true;
        case ConstructionDimension::Face:   Raised = ConstructionDimension::Solid; return true;  // directly; no closure flag applies
        // A sealed shell IS the boundary of a solid. An open one has nothing to raise.
        case ConstructionDimension::Shell:
            if (ClosedCondition) { Raised = ConstructionDimension::Solid; return true; }
            return false;
        case ConstructionDimension::Solid: return false;  // 🔴 no successor in the chain
        default: return false;                            // Nothing — nothing to raise
    }
}

const char* DescribeLaw(ConstructionDimension Dimension, bool ClosedCondition)
{
    switch (Dimension)
    {
        case ConstructionDimension::Vertex: return "A swept point traces a curve — dimension rises by one.";
        case ConstructionDimension::Edge:   return "A swept curve sweeps out a surface.";
        case ConstructionDimension::Wire:   return ClosedCondition
            ? "A closed wire bounds a face, and a face raises to a solid."
            : "🔴 An open wire raises to a shell. There is no path to Solid.";
        case ConstructionDimension::Face:   return "A face raises to a solid directly — no closure flag applies.";
        case ConstructionDimension::Shell:  return ClosedCondition
            ? "A sealed shell is already the boundary of a solid."
            : "An open shell has no successor — nothing to raise.";
        case ConstructionDimension::Solid:  return "🔴 Solid is the top of the chain. It has no successor.";
        default: return "No input selected — creation is unconditioned.";
    }
}

//----------------------------------------------------------------------------------------------------------------------
//                                                          THE GATE
//----------------------------------------------------------------------------------------------------------------------

GateResult EvaluateOperation(const ConstructionOperation& Operation, const ConstructionDocument& Document)
{
    // ① Dimension. AcceptsAnyGeometry means every dimension EXCEPT Nothing; otherwise the explicit mask.
    const unsigned int ActiveBit = 1u << static_cast<unsigned int>(Document.ActiveDimension);
    const bool NothingActive = (Document.ActiveDimension == ConstructionDimension::Nothing);
    if (Operation.AcceptsAnyGeometry)
    {
        if (NothingActive) return GateResult::DimensionMismatch;
    }
    else if ((Operation.DimensionMask & ActiveBit) == 0u)
    {
        return GateResult::DimensionMismatch;
    }

    // ② The workplane, promoted above every other requirement so its remedy can be offered.
    const unsigned int WorkplaneBit = 1u << Requirement_Workplane;
    if ((Operation.NeedMask & WorkplaneBit) != 0u && !Document.WorkplaneActivation) return GateResult::WorkplaneAbsent;

    // ③ Counts. Each is its own diagnostic — "exactly 2" and "2 to 4 edges" are different fixes.
    if (Operation.MinimumCount   && Document.SelectedCount       <  Operation.MinimumCount)   return GateResult::ProfileShortfall;
    if (Operation.MinimumProfile && Document.ProfileCount        <  Operation.MinimumProfile) return GateResult::ProfileShortfall;
    if (Operation.ExactSolid     && Document.SolidCount         != Operation.ExactSolid)      return GateResult::ProfileShortfall;
    if (Operation.MinimumSolid   && Document.SolidCount          <  Operation.MinimumSolid)   return GateResult::ProfileShortfall;
    if (Operation.MinimumCircle  && Document.ExistingCircleCount <  Operation.MinimumCircle)  return GateResult::ProfileShortfall;
    if (Operation.BoundaryPresent)
    {
        if (Document.BoundaryEdgeCount < Operation.BoundaryFloor || Document.BoundaryEdgeCount > Operation.BoundaryCeiling)
            return GateResult::ProfileShortfall;
    }

    // ④ The remaining input facts. Workplane is already resolved at ②.
    for (int Key = 0; Key < ConstructionRequirementCount; ++Key)
    {
        if (Key == Requirement_Workplane) continue;
        if ((Operation.NeedMask & (1u << Key)) == 0u) continue;
        if (!DocumentFieldSet(Key, Document)) return GateResult::ProfileShortfall;
    }

    // ⑤ 🔴 Closure — a LIVE state, not a failure. The op runs; the badge states the truthful result the law predicts.
    if (Operation.RaisesDimension)
    {
        ConstructionDimension Raised;
        if (!RaiseDimension(Document.ActiveDimension, Document.ClosedProfileCondition, Raised))
            return GateResult::DimensionMismatch;              // no successor — hide, do not grey
        if (Raised != ConstructionDimension::Solid) return GateResult::ClosureShortfall;  // runs, but you get a shell
    }
    return GateResult::Available;
}

const char* ShortfallText(const ConstructionOperation& Operation, const ConstructionDocument& Document,
                          char* Destination, int Capacity)
{
    const unsigned int WorkplaneBit = 1u << Requirement_Workplane;
    if ((Operation.NeedMask & WorkplaneBit) != 0u && !Document.WorkplaneActivation)
    {
        std::snprintf(Destination, static_cast<size_t>(Capacity), "%s", RequirementShortfall[Requirement_Workplane]);
        return Destination;
    }
    if (Operation.MinimumCount && Document.SelectedCount < Operation.MinimumCount)
    { std::snprintf(Destination, static_cast<size_t>(Capacity), "needs %d selected", Operation.MinimumCount); return Destination; }
    if (Operation.MinimumProfile && Document.ProfileCount < Operation.MinimumProfile)
    { std::snprintf(Destination, static_cast<size_t>(Capacity), "needs %d profiles", Operation.MinimumProfile); return Destination; }
    if (Operation.ExactSolid && Document.SolidCount != Operation.ExactSolid)
    { std::snprintf(Destination, static_cast<size_t>(Capacity), "needs exactly %d", Operation.ExactSolid); return Destination; }
    if (Operation.MinimumSolid && Document.SolidCount < Operation.MinimumSolid)
    { std::snprintf(Destination, static_cast<size_t>(Capacity), "needs %d solids", Operation.MinimumSolid); return Destination; }
    if (Operation.MinimumCircle && Document.ExistingCircleCount < Operation.MinimumCircle)
    { std::snprintf(Destination, static_cast<size_t>(Capacity), "needs %d circles", Operation.MinimumCircle); return Destination; }
    if (Operation.BoundaryPresent &&
        (Document.BoundaryEdgeCount < Operation.BoundaryFloor || Document.BoundaryEdgeCount > Operation.BoundaryCeiling))
    {
        if (Operation.BoundaryFloor == Operation.BoundaryCeiling)
            std::snprintf(Destination, static_cast<size_t>(Capacity), "needs %d edges", Operation.BoundaryFloor);
        else
            std::snprintf(Destination, static_cast<size_t>(Capacity), "needs %d\u2013%d edges", Operation.BoundaryFloor, Operation.BoundaryCeiling);
        return Destination;
    }
    for (int Key = 0; Key < ConstructionRequirementCount; ++Key)
    {
        if ((Operation.NeedMask & (1u << Key)) == 0u) continue;
        if (!DocumentFieldSet(Key, Document))
        { std::snprintf(Destination, static_cast<size_t>(Capacity), "%s", RequirementShortfall[Key]); return Destination; }
    }
    std::snprintf(Destination, static_cast<size_t>(Capacity), "unavailable");
    return Destination;
}

bool ResultType(const ConstructionOperation& Operation, const ConstructionDocument& Document, ConstructionDimension& Result)
{
    if (!Operation.RaisesDimension) return false;
    return RaiseDimension(Document.ActiveDimension, Document.ClosedProfileCondition, Result);
}

//----------------------------------------------------------------------------------------------------------------------
//                                                    RENDERING PREDICATES
//----------------------------------------------------------------------------------------------------------------------

bool OperationOmitted(const ConstructionOperation& Operation, const ConstructionDocument& Document)
{ return EvaluateOperation(Operation, Document) == GateResult::DimensionMismatch; }

bool OperationGated(const ConstructionOperation& Operation, const ConstructionDocument& Document)
{
    const GateResult Verdict = EvaluateOperation(Operation, Document);
    return Verdict == GateResult::WorkplaneAbsent || Verdict == GateResult::ProfileShortfall;
}

bool OperationFixable(const ConstructionOperation& Operation, const ConstructionDocument& Document)
{ return EvaluateOperation(Operation, Document) == GateResult::WorkplaneAbsent; }

bool OperationLive(const ConstructionOperation& Operation, const ConstructionDocument& Document)
{
    const GateResult Verdict = EvaluateOperation(Operation, Document);
    return Verdict == GateResult::Available || Verdict == GateResult::ClosureShortfall;
}

ConstructionTally TallyBuckets(const ConstructionDocument& Document)
{
    ConstructionTally Result = { 0, 0, 0, 0 };
    for (int BandIndex = 0; BandIndex < ConstructionBandCount; ++BandIndex)
    {
        const ConstructionBand& Band = ConstructionBands[BandIndex];
        for (int OpIndex = 0; OpIndex < Band.OperationCount; ++OpIndex)
        {
            const ConstructionOperation& Operation = Band.Operations[OpIndex];
            if (OperationOmitted(Operation, Document))      ++Result.Hidden;
            else if (OperationGated(Operation, Document))   ++Result.Gated;
            else                                            ++Result.Available;
        }
    }
    Result.Total = Result.Available + Result.Gated + Result.Hidden;
    return Result;
}

//----------------------------------------------------------------------------------------------------------------------
//                                                        ACCESSORS
//----------------------------------------------------------------------------------------------------------------------

const ConstructionBand* ResolveConstructionBands(int& BandCount)
{
    BandCount = ConstructionBandCount;
    return ConstructionBands;
}

const char* DescribeDimension(ConstructionDimension Dimension)
{
    switch (Dimension)
    {
        case ConstructionDimension::Nothing: return "Nothing";
        case ConstructionDimension::Vertex: return "Vertex";
        case ConstructionDimension::Edge: return "Edge";
        case ConstructionDimension::Wire: return "Wire";
        case ConstructionDimension::Face: return "Face";
        case ConstructionDimension::Shell: return "Shell";
        case ConstructionDimension::Solid: return "Solid";
        default: return "Nothing";
    }
}

ConstructionDocument DefaultConstructionDocument()
{
    ConstructionDocument Document = {};
    Document.ActiveDimension          = ConstructionDimension::Nothing;
    Document.SelectedCount            = 0;
    Document.ProfileCount             = 0;
    Document.BoundaryEdgeCount        = 0;
    Document.ExistingCircleCount      = 0;
    Document.SolidCount               = 0;
    Document.WorkplaneActivation       = false;
    Document.ClosedProfileCondition    = false;
    Document.PlanarProfileCondition    = true;
    Document.AxisAvailability          = false;
    Document.PathAvailability          = false;
    Document.UniformClosureCondition   = true;
    Document.PendingGeometryCondition  = false;
    Document.SupportMaterialCondition  = false;
    Document.TangentEndpointCondition  = false;
    Document.OpeningCondition          = false;
    Document.ReferencePlaneCondition   = false;
    Document.SourceImageryCondition    = false;
    Document.MeasurableCondition       = false;
    return Document;
}

